    Map<Integer, Integer> countMap = new HashMap<>();
    for (int num : arr) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }

    // Iterate over the hash map and check if the sum of each pair is divisible by k
    for (int num : countMap.keySet()) {
        int count = countMap.get(num);
        if (count > 0 && num % k == 0) {
            count--;
            if (count > 0) {
                int complement = (num / k) * k - num;
                if (countMap.containsKey(complement)) {
                    int complementCount = countMap.get(complement);
                    if (complementCount > 0) {
                        complementCount--;
