public static int singleNumber(int[] nums) {
    // Step 1: Initialize a hash set to store all unique elements in the array
    Set<Integer> uniqueSet = new HashSet<>();

    // Step 2: Iterate over the array and add all elements to the hash set
    for (int num : nums) {
        uniqueSet.add(num);
    }

    // Step 3: Iterate over the array again and find the single element that is not in the hash set
    for (int num : nums) {
        if (!uniqueSet.contains(num)) {
            return num;
        }
    }

