    int n = mat[0].length;
    int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            for (int[] dir : directions) {
                int currLength = 0;
                int currX = i;
                int currY = j;
