}

public static int[] diagonalOrder(int[][] mat) {
    int[] result = new int[mat.length * mat[0].length];
    int index = 0;
    int rowStart = 0, rowEnd = mat.length - 1, colStart = 0, colEnd = mat[0].length - 1;
    while (rowStart <= rowEnd && colStart <= colEnd) {
        for (int col = colStart; col <= colEnd; col++) {
            result[index++] = mat[rowStart][col];
        }
        rowStart++;
        for (int row = rowStart; row <= rowEnd; row++) {
            result[index++] = mat[row][colEnd];
        }
        colEnd--;
        if (rowStart <= rowEnd) {
            for (int col = colEnd; col >= colStart; col--) {
                result[index++] = mat[rowEnd][col];
            }
            rowEnd--;
        }
        if (colStart <= colEnd) {
            for (int row = rowEnd; row >= rowStart; row--) {
                result[index++] = mat[row][colStart];
            }
            colStart++;
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {

        // Convert the input to a string of individual digits
        String nDigits = String.valueOf(n);

        // Array to store the digits of n in sorted order
        int[] sortedDigits = new int[nDigits.length()];

        // Sort the digits of n in ascending order
        for (int i = 0; i < nDigits.length(); i++) {
            sortedDigits[i] = Character.getNumericValue(nDigits.charAt(i));
        }
        Arrays.sort(sortedDigits);

        // Check if the digits are in sorted order
        int smallestDigit = sortedDigits[0];
        for (int i = 1; i < sortedDigits.length; i++) {
            if (sortedDigits[i] < smallestDigit) {
                smallestDigit = sortedDigits[i];
            }
        }

        // If the digits are already sorted, return -1
        if (smallestDigit == Character.getNumericValue(nDigits.charAt(0))) {
            return -1;
        }

        // Swap the smallest digit with the first digit
        if (smallestDigit != 0) {
            nDigits = nDigits.substring(0, nDigits.length() - 1) + smallestDigit + "0";
        } else {
            nDigits = "0" + nDigits.substring(nDigits.length() - 1);
        }

        // Return the smallest rearranged integer greater than n
        return Integer.parseInt(nDigits);
    }

public static List<String> centerSymmetricNumbers(int n) {
    List<String> numbers = new ArrayList<>();
    if (n < 1) {
        return numbers;
    }
    int min = (int) Math.pow(10, n - 1);
    int max = (int) Math.pow(10, n) - 1;
    for (int i = min; i <= max; i++) {
        String number = String.valueOf(i);
        if (isCenterSymmetric(number)) {
            numbers.add(number);
        }
    }
    return numbers;
}

private static boolean isCenterSymmetric(String number) {
    int len = number.length();
    for (int i = 0; i < len / 2; i++) {
        if (number.charAt(i) != number.charAt(len - i - 1)) {
            return false;
        }
    }
    return true;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The input array must have exactly 3 points.");
    }
    int[] xVals = new int[3];
    int[] yVals = new int[3];
    for (int i = 0; i < 3; i++) {
        xVals[i] = points[i][0];
        yVals[i] = points[i][1];
    }
    // calculate the slopes of the lines defined by the 3 points
    double s1 = (double)(yVals[1] - yVals[0]) / (xVals[1] - xVals[0]);
    double s2 = (double)(yVals[2] - yVals[1]) / (xVals[2] - xVals[1]);
    double s3 = (double)(yVals[2] - yVals[0]) / (xVals[2] - xVals[0]);
    // check if the slopes of the lines are equal
    return (s1 == s2) && (s2 == s3);
}

public static int findNthUglyNumber(int n) {
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0;
    int i3 = 0;
    int i5 = 0;
    int min;

    for (int i = 1; i < n; i++) {
        min = Math.min(ugly[i2] * 2, Math.min(ugly[i3] * 3, ugly[i5] * 5));
        ugly[i] = min;
        if (min == ugly[i2] * 2) i2++;
        if (min == ugly[i3] * 3) i3++;
        if (min == ugly[i5] * 5) i5++;
    }

    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 0;
    // Find the longest non-empty substring containing only one character
    int start = 0, end = 0;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            end = i;
        } else {
            start = i;
            energy = Math.max(energy, end - start);
        }
    }
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result);
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> unique = new HashSet<>();
    for (int num : nums) {
        unique.add(num);
    }
    int sum = 0;
    for (int num : unique) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 1) { // invalid input
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int minNumSquares = 1;
    int perfectSquare = 1;
    while (perfectSquare <= n) {
        int remaining = n - perfectSquare;
        int nextSquare = perfectSquare + 1;
        if (nextSquare * nextSquare > remaining) {
            break;
        }
        perfectSquare = nextSquare;
        minNumSquares++;
    }
    return minNumSquares;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        result.append(reverse(word)).append(" ");
    }
    return result.toString().trim();
}

private static String reverse(String s) {
    StringBuilder result = new StringBuilder(s);
    for (int i = 0; i < s.length() / 2; i++) {
        result.setCharAt(i, s.charAt(s.length() - 1 - i));
        result.setCharAt(s.length() - 1 - i, s.charAt(i));
    }
    return result.toString();
}
